stepxmp.pre:
title {
    color: var(--accent, black);
    margin-left: calc(var(--gap) * 2);
}

@property --size {
    syntax: "<length>";
    inherits: false;
    initial-value: 20pt;
}

title {
    margin-left: var(--size);
}

figure::before {
    content: attr(title);
}

figure {
    width: attr(data-width <length>, 100pt);
    border-color: attr(tint <color>, black);
}

@function --double(--x <length>) returns <length> {
    result: calc(var(--x) * 2);
}

@function --pad(--x <length>: 4pt) returns <length> {
    --y: calc(var(--x) * 2);
    result: var(--y);
}

title {
    margin-left: --double(10pt);
    margin-right: --pad();
}
